 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Border bars send perpendicular rays of the singleton-marker color.
    # Each ray fills background cells until it reaches a marker (which becomes 4).
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 1:
                end = c
                while end + 1 < w and grid[r][end + 1] == 1:
                    end += 1
                bars.append((r, c, end))
                c = end + 1
            else:
                c += 1

    for edge_row, start, end in bars:
        dr = 1 if edge_row == 0 else -1
        for c in range(start, end + 1):
            r = edge_row + dr
            while 0 <= r < h:
                if grid[r][c] == 3:
                    out[r][c] = 4
                    break
                out[r][c] = 3
                r += dr
    # Recolor all marker cells even if a ray does not encounter them.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 4
    return out

