 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))

    # Opposite edge bars of the same color form the pair of rails.
    pair = None
    for horizontal in (False, True):  # side bars, then top/bottom bars
        run_len = w if not horizontal else h
        edge_count = h if not horizontal else w
        edge_runs = []
        for edge in (0, edge_count - 1):
            runs, i = [], 0
            while i < run_len:
                r, c = (edge, i) if horizontal else (i, edge)
                color = grid[r][c]
                if color == bg:
                    i += 1
                    continue
                j = i
                while j + 1 < run_len:
                    rr, cc = (edge, j + 1) if horizontal else (j + 1, edge)
                    if grid[rr][cc] != color:
                        break
                    j += 1
                runs.append((color, i, j))
                i = j + 1
            edge_runs.append(runs)
        matches = [(a, b) for a in edge_runs[0] for b in edge_runs[1]
                   if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]]
        if matches:
            pair = (horizontal, matches[0][0], matches[0][1], edge_count)
            break
    if pair is None:
        return out

    horizontal, bar_a, bar_b, edge_count = pair
    rail_color = bar_a[0]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != rail_color]
    if not markers:
        return out
    marker_color = grid[markers[0][0]][markers[0][1]]
    markers = [(r, c) for r, c in markers if grid[r][c] == marker_color]

    # A marker within a rail's span activates its relative position on both rails.
    active = set()
    for r, c in markers:
        pos = c if horizontal else r
        for _, start, end in (bar_a, bar_b):
            if start <= pos <= end:
                active.add(pos - start)

    # Project activated positions inward from both rails, stopping at markers.
    for which, bar in enumerate((bar_a, bar_b)):
        _, start, end = bar
        edge = 0 if which == 0 else edge_count - 1
        step = 1 if edge == 0 else -1
        for offset in active:
            pos = start + offset
            if pos > end:
                continue
            for d in range(1, edge_count):
                cross = edge + step * d
                if not 0 <= cross < edge_count:
                    break
                if horizontal:
                    r, c = cross, pos
                else:
                    r, c = pos, cross
                if grid[r][c] == marker_color:
                    out[r][c] = 4
                    break
                if grid[r][c] == bg:
                    out[r][c] = marker_color

    for r, c in markers:
        out[r][c] = 4
    return out

if __name__ == '__main__':
