 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    background = max(colors, key=lambda v: sum(row.count(v) for row in grid))

    # Locate equal-length, same-color runs on opposing borders.
    pair = None
    for horizontal in (True, False):
        along_len = w if horizontal else h
        cross_len = h if horizontal else w
        runs_by_edge = []
        for edge in (0, cross_len - 1):
            runs = []
            i = 0
            while i < along_len:
                r, c = (edge, i) if horizontal else (i, edge)
                color = grid[r][c]
                if color == background:
                    i += 1
                    continue
                j = i
                while j + 1 < along_len:
                    rr, cc = (edge, j + 1) if horizontal else (j + 1, edge)
                    if grid[rr][cc] != color:
                        break
                    j += 1
                runs.append((color, i, j))
                i = j + 1
            runs_by_edge.append(runs)
        matches = [(a, b) for a in runs_by_edge[0] for b in runs_by_edge[1]
                   if a[0] == b[0] and a[0] != background
                   and a[2] - a[1] == b[2] - b[1]]
        if matches:
            pair = horizontal, matches[0][0], matches[0][1], cross_len
            break
    if pair is None:
        return out

    horizontal, rail_a, rail_b, cross_len = pair
    rail_color = rail_a[0]
    marker_groups = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != background and value != rail_color:
                marker_groups.setdefault(value, []).append((r, c))
    if not marker_groups:
        return out
    marker_color, markers = max(marker_groups.items(), key=lambda item: len(item[1]))

    # Each marker activates the matching offset on either rail it aligns with.
    active_offsets = set()
    for r, c in markers:
        pos = c if horizontal else r
        for _, start, end in (rail_a, rail_b):
            if start <= pos <= end:
                active_offsets.add(pos - start)

    # Rays from both rails cross the grid. They paint background with the
    # marker color, stop at markers (turning them into 4), and preserve rails.
    for side, rail in enumerate((rail_a, rail_b)):
        _, start, end = rail
        edge = 0 if side == 0 else cross_len - 1
        step = 1 if side == 0 else -1
        for offset in active_offsets:
            along = start + offset
            if not start <= along <= end:
                continue
            for distance in range(1, cross_len):
                cross = edge + step * distance
                if not 0 <= cross < cross_len:
                    break
                r, c = (cross, along) if horizontal else (along, cross)
                if grid[r][c] == marker_color:
                    out[r][c] = 4
                    break
                if grid[r][c] != background:
                    break
                out[r][c] = marker_color

    for r, c in markers:
