    active = set()
    for r, c in markers:
        pos = c if horizontal else r
        for _, a, b in ((None, rail_a[1], rail_a[2]), (None, rail_b[1], rail_b[2])):
            if a <= pos <= b:
                active.add(pos - a)

    # Project from each guide bar perpendicular to it, using the marker color.
    # For each bar offset, trace until a marker or the opposite outer edge.
    for side, rail in enumerate((rail_a, rail_b)):
        _, start, end = rail
        edge = 0 if side == 0 else (h-1 if horizontal else w-1)
        step = 1 if side == 0 else -1
        for offset in active:
