    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))

    # Paired border bars identify two perpendicular beams in the marker color.
    # The beam depth is the number of consecutive border cells of its color.
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in [(rr, cc) for rr in range(h) for cc in range(w) if False]]
    # Keep border-rail color separate from the sparse interior marker color.
    border_counts = {}
    for c in range(w):
        border_counts[grid[0][c]] = border_counts.get(grid[0][c], 0) + 1
        border_counts[grid[h-1][c]] = border_counts.get(grid[h-1][c], 0) + 1
    for r in range(h):
        border_counts[grid[r][0]] = border_counts.get(grid[r][0], 0) + 1
        border_counts[grid[r][w-1]] = border_counts.get(grid[r][w-1], 0) + 1
    rail_color = max((v for v in border_counts if v != bg), key=lambda v: border_counts[v], default=None)
    if rail_color is None:
        return out
    marker_cells = [(r, c) for r in range(h) for c in range(w)
                    if grid[r][c] != bg and grid[r][c] != rail_color]
    if not marker_cells:
        return out
    marker_color = max({grid[r][c] for r, c in marker_cells},
                       key=lambda v: sum(grid[r][c] == v for r, c in marker_cells))
    markers = [(r, c) for r, c in marker_cells if grid[r][c] == marker_color]
    for r, c in markers:
        out[r][c] = 4

    # Find straight rail runs on the four edges.
    top = [c for c in range(w) if grid[0][c] == rail_color]
    bottom = [c for c in range(w) if grid[h-1][c] == rail_color]
    left = [r for r in range(h) if grid[r][0] == rail_color]
    right = [r for r in range(h) if grid[r][w-1] == rail_color]

    # A bar projects the marker color perpendicular to its edge, over its span,
    # stopping at the first original marker; marker positions turn into 4.
    for cols, edge, step in ((top, 0, 1), (bottom, h-1, -1)):
        if len(cols) >= 2:
            for c in cols:
                rr = edge + step
                while 0 <= rr < h:
                    if grid[rr][c] == marker_color:
                        out[rr][c] = 4
                        break
                    if grid[rr][c] != bg:
                        break
                    out[rr][c] = marker_color
                    rr += step
    for rows, edge, step in ((left, 0, 1), (right, w-1, -1)):
        if len(rows) >= 2:
            for r in rows:
                cc = edge + step
                while 0 <= cc < w:
                    if grid[r][cc] == marker_color:
                        out[r][cc] = 4
                        break
                    if grid[r][cc] != bg:
                        break
                    out[r][cc] = marker_color
