    edge_counts = {}
    for c in range(w):
        edge_counts[grid[0][c]] = edge_counts.get(grid[0][c], 0) + 1
        edge_counts[grid[h - 1][c]] = edge_counts.get(grid[h - 1][c], 0) + 1
    for r in range(h):
        edge_counts[grid[r][0]] = edge_counts.get(grid[r][0], 0) + 1
        edge_counts[grid[r][w - 1]] = edge_counts.get(grid[r][w - 1], 0) + 1
    rail = max((v for v in edge_counts if v != bg), key=edge_counts.get, default=None)
    if rail is None:
        return out

    markers = [(r, c) for r in range(h) for c in range(w)
