    def edge_runs(horizontal, edge):
        length = w if horizontal else h
        runs = []
        i = 0
        while i < length:
            r, c = (edge, i) if horizontal else (i, edge)
            color = grid[r][c]
            if color == background:
                i += 1
                continue
            j = i
            while j + 1 < length:
                rr, cc = (edge, j + 1) if horizontal else (j + 1, edge)
                if grid[rr][cc] != color:
                    break
                j += 1
            runs.append((color, i, j))
            i = j + 1
        return runs

