    pairs = []
    for horizontal in (True, False):
        cross = h if horizontal else w
        first = edge_runs(horizontal, 0)
        second = edge_runs(horizontal, cross - 1)
        for a in first:
            for b in second:
                if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                    pairs.append((a[2] - a[1] + 1, horizontal, a, b))
    if not pairs:
        return out
    _, horizontal, rail_a, rail_b = max(pairs, key=lambda item: (item[0], item[1]))
    rail_color = rail_a[0]

