    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    # Markers select offsets along either rail. The same offsets project from
    # both opposing bars; rays stop at a marker, or continue to the far border.
    active_offsets = set()
    for r, c in markers:
        pos = c if horizontal else r
        for rail in (rail_a, rail_b):
            if rail[1] <= pos <= rail[2]:
                active_offsets.add(pos - rail[1])

    for side, rail in enumerate((rail_a, rail_b)):
        start, end = rail[1], rail[2]
        edge = 0 if side == 0 else (h - 1 if horizontal else w - 1)
        step = 1 if side == 0 else -1
        cross_size = h if horizontal else w
        for offset in active_offsets:
