        runs = []
        i = 0
        while i < length:
            r, c = (edge, i) if horizontal else (i, edge)
            color = grid[r][c]
            if color == background:
                i += 1
                continue
            j = i
            while j + 1 < length:
                rr, cc = (edge, j + 1) if horizontal else (j + 1, edge)
                if grid[rr][cc] != color:
                    break
                j += 1
            runs.append((color, i, j))
            i = j + 1
        return runs

    # Same-color, same-length runs on opposite edges are the paired rails.
    candidates = []
    for horizontal in (True, False):
        cross_size = h if horizontal else w
        edge_a = runs_on_edge(horizontal, 0)
        edge_b = runs_on_edge(horizontal, cross_size - 1)
        for a in edge_a:
            for b in edge_b:
                if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                    candidates.append((a[2] - a[1] + 1, horizontal, a, b))
    if not candidates:
        return out
    _, horizontal, rail_a, rail_b = max(candidates, key=lambda item: (item[0], item[1]))
    rail_color = rail_a[0]

    marker_counts = {}
    for row in grid:
        for value in row:
            if value != background and value != rail_color:
                marker_counts[value] = marker_counts.get(value, 0) + 1
    if not marker_counts:
        return out
    marker_color = max(marker_counts, key=marker_counts.get)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    # A marker's offset within either rail activates the same offset on both.
    offsets = set()
    for r, c in markers:
        pos = c if horizontal else r
        for rail in (rail_a, rail_b):
            if rail[1] <= pos <= rail[2]:
                offsets.add(pos - rail[1])

    cross_size = h if horizontal else w
    for side, rail in enumerate((rail_a, rail_b)):
        along_start, along_end = rail[1], rail[2]
        edge = 0 if side == 0 else cross_size - 1
        step = 1 if side == 0 else -1
        for offset in offsets:
            along = along_start + offset
            if along > along_end:
                continue
            cross = edge + step
            while 0 <= cross < cross_size:
                r, c = (cross, along) if horizontal else (along, cross)
                if grid[r][c] == marker_color:
                    out[r][c] = 4
                    break
                if grid[r][c] != background:
                    break
                out[r][c] = marker_color
                cross += step

    # Mark all original markers as endpoints, even if not intersected by a ray.
    for r, c in markers:
        out[r][c] = 4
    return out

