        second_runs = edge_runs(horizontal, cross_size - 1)
        for first in first_runs:
            for second in second_runs:
                if (first[0] == second[0]
                        and first[2] - first[1] == second[2] - second[1]):
                    candidates.append((first[2] - first[1] + 1,
                                       horizontal, first, second))
    if not candidates:
        return out
    _, horizontal, rail_a, rail_b = max(candidates, key=lambda item: (item[0], item[1]))
    rail_color = rail_a[0]

    # Interior cells of the remaining non-background color are marker endpoints.
    marker_counts = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != background and value != rail_color:
                marker_counts[value] = marker_counts.get(value, 0) + 1
    if not marker_counts:
        return out
    marker_color = max(marker_counts, key=marker_counts.get)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    # Marker positions select offsets in a rail. Project those offsets from
    # both matching rails; rays continue through background and stop at objects.
    active_offsets = set()
    for r, c in markers:
        position = c if horizontal else r
        for rail in (rail_a, rail_b):
            if rail[1] <= position <= rail[2]:
                active_offsets.add(position - rail[1])

    cross_size = h if horizontal else w
    for side, rail in enumerate((rail_a, rail_b)):
        cross = 0 if side == 0 else cross_size - 1
        step = 1 if side == 0 else -1
        for offset in active_offsets:
            along = rail[1] + offset
            while 0 <= cross < cross_size:
                r, c = (cross, along) if horizontal else (along, cross)
                value = grid[r][c]
                if value == marker_color:
                    out[r][c] = 4
                    break
                if value != background:
                    break
                out[r][c] = marker_color
                cross += step

    for r, c in markers:
        out[r][c] = 4
    return out

